import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const DashboardLayout = ({ children }) => {
  const { user, logout, isAdmin, isManager, isCashier, isChef, isWaiter } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  // Detectar scroll para sombra en navbar desktop
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Cerrar menú móvil al cambiar de ruta
  useEffect(() => {
    setMobileOpen(false);
  }, [location.pathname]);

  const menuItems = [
    ...(isWaiter ? [{ path: '/waiter', icon: '📝', label: 'Tomar Pedido' }] : []),
    ...(isChef ? [{ path: '/kitchen', icon: '👨‍🍳', label: 'Cocina' }] : []),
    ...(isCashier ? [{ path: '/cashier', icon: '💰', label: 'Caja' }] : []),
    ...(isManager ? [
      { path: '/admin/dashboard', icon: '📊', label: 'Dashboard' },
      { path: '/admin/reports', icon: '📈', label: 'Reportes' },
      { path: '/admin/reservations', icon: '📅', label: 'Reservas' },
      { path: '/admin/menu', icon: '🍽️', label: 'Menú' },
      { path: '/admin/categories', icon: '🗂️', label: 'Categorías' },
      { path: '/admin/modifiers', icon: '⚙️', label: 'Modificadores' },
      { path: '/admin/tables', icon: '🪑', label: 'Mesas' },
    ] : []),
    ...(isAdmin ? [
      { path: '/admin/users', icon: '👥', label: 'Usuarios' },
    ] : []),
  ];

  const isActive = (path) => location.pathname === path || location.pathname.startsWith(path + '/');

  // ─── PALETA DE COLORES (basada en tu documento) ───
  const colors = {
    primary: '#E67E22',
    primaryHover: '#D36C1A',
    primaryPressed: '#B55912',
    textDark: '#333333',
    textSecondary: '#70757A',
    bgLight: '#FFFFFF',
    bgSecondary: '#F8F9FA',
    border: '#E5E7EB',
    success: '#27AE60',
    warning: '#F1C40F',
    error: '#E74C3C',
    info: '#3498DB',
  };

  return (
    <div style={{ minHeight: '100vh', background: colors.bgSecondary, fontFamily: "'Inter', 'Segoe UI', system-ui, sans-serif" }}>

      {/* ═══════════════════════════════════════
          NAVBAR SUPERIOR — VERSIÓN DESKTOP (≥1024px)
          ═══════════════════════════════════════ */}
      <header
        style={{
          display: 'none',
          '@media (min-width: 1024px)': { display: 'flex' },
        }}
        className="desktop-navbar"
      >
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            height: 72,
            background: colors.bgLight,
            borderBottom: `1px solid ${colors.border}`,
            boxShadow: scrolled ? '0 4px 20px rgba(0,0,0,0.08)' : '0 1px 3px rgba(0,0,0,0.05)',
            zIndex: 1000,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            padding: '0 32px',
            transition: 'box-shadow 0.3s ease',
          }}
        >
          {/* Logo */}
          <div
            onClick={() => navigate('/')}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
              cursor: 'pointer',
              userSelect: 'none',
            }}
          >
            <div
              style={{
                width: 42,
                height: 42,
                borderRadius: 12,
                background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: 22,
                boxShadow: `0 4px 12px ${colors.primary}40`,
              }}
            >
              🍽️
            </div>
            <span style={{ fontSize: 20, fontWeight: 800, color: colors.textDark, letterSpacing: '-0.5px' }}>
              Restaurant <span style={{ color: colors.primary }}>AR</span>
            </span>
          </div>

          {/* Navegación Central */}
          <nav style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1, justifyContent: 'center' }}>
            {menuItems.map((item) => {
              const active = isActive(item.path);
              return (
                <button
                  key={item.path}
                  onClick={() => navigate(item.path)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 8,
                    padding: '10px 18px',
                    borderRadius: 10,
                    border: 'none',
                    background: active ? `${colors.primary}15` : 'transparent',
                    color: active ? colors.primary : colors.textSecondary,
                    fontSize: 14,
                    fontWeight: active ? 600 : 500,
                    cursor: 'pointer',
                    transition: 'all 0.2s ease',
                    position: 'relative',
                    whiteSpace: 'nowrap',
                  }}
                  onMouseEnter={(e) => {
                    if (!active) {
                      e.currentTarget.style.background = `${colors.primary}0D`;
                      e.currentTarget.style.color = colors.textDark;
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (!active) {
                      e.currentTarget.style.background = 'transparent';
                      e.currentTarget.style.color = colors.textSecondary;
                    }
                  }}
                >
                  <span style={{ fontSize: 16 }}>{item.icon}</span>
                  {item.label}
                  {active && (
                    <span
                      style={{
                        position: 'absolute',
                        bottom: -2,
                        left: '50%',
                        transform: 'translateX(-50%)',
                        width: 20,
                        height: 3,
                        borderRadius: 2,
                        background: colors.primary,
                      }}
                    />
                  )}
                </button>
              );
            })}
          </nav>

          {/* Perfil + Dropdown */}
          <div style={{ position: 'relative' }}>
            <button
              onClick={() => setUserMenuOpen(!userMenuOpen)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                padding: '6px 6px 6px 16px',
                borderRadius: 50,
                border: `1px solid ${colors.border}`,
                background: colors.bgLight,
                cursor: 'pointer',
                transition: 'all 0.2s',
              }}
            >
              <div style={{ textAlign: 'right' }}>
                <p style={{ margin: 0, fontSize: 13, fontWeight: 600, color: colors.textDark, lineHeight: 1.2 }}>
                  {user?.name}
                </p>
                <p style={{ margin: 0, fontSize: 11, color: colors.textSecondary, lineHeight: 1.2 }}>
                  {user?.role?.name}
                </p>
              </div>
              <div
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: '50%',
                  background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontWeight: 700,
                  color: '#fff',
                  fontSize: 14,
                  flexShrink: 0,
                }}
              >
                {user?.name?.charAt(0)?.toUpperCase()}
              </div>
              <span style={{ fontSize: 10, color: colors.textSecondary, marginLeft: 2 }}>▼</span>
            </button>

            {/* Dropdown */}
            {userMenuOpen && (
              <>
                <div
                  onClick={() => setUserMenuOpen(false)}
                  style={{
                    position: 'fixed',
                    inset: 0,
                    zIndex: -1,
                  }}
                />
                <div
                  style={{
                    position: 'absolute',
                    top: 'calc(100% + 8px)',
                    right: 0,
                    width: 220,
                    background: colors.bgLight,
                    borderRadius: 16,
                    border: `1px solid ${colors.border}`,
                    boxShadow: '0 20px 40px rgba(0,0,0,0.12)',
                    padding: 8,
                    zIndex: 1001,
                    animation: 'fadeInDown 0.2s ease',
                  }}
                >
                  <div style={{ padding: '12px 16px', borderBottom: `1px solid ${colors.border}`, marginBottom: 4 }}>
                    <p style={{ margin: 0, fontSize: 14, fontWeight: 700, color: colors.textDark }}>
                      {user?.name}
                    </p>
                    <p style={{ margin: 0, fontSize: 12, color: colors.textSecondary, marginTop: 2 }}>
                      {user?.email || user?.role?.name}
                    </p>
                  </div>
                  <button
                    onClick={() => {
                      setUserMenuOpen(false);
                      logout();
                    }}
                    style={{
                      width: '100%',
                      display: 'flex',
                      alignItems: 'center',
                      gap: 10,
                      padding: '10px 14px',
                      borderRadius: 10,
                      border: 'none',
                      background: 'transparent',
                      color: colors.error,
                      fontSize: 14,
                      fontWeight: 500,
                      cursor: 'pointer',
                      transition: 'background 0.2s',
                      textAlign: 'left',
                    }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = `${colors.error}10`)}
                    onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
                  >
                    🚪 Cerrar Sesión
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      </header>

      {/* CSS para mostrar el navbar desktop y ocultar móvil */}
      <style>{`
        @media (min-width: 1024px) {
          .desktop-navbar { display: flex !important; }
          .mobile-header { display: none !important; }
          .mobile-sidebar { display: none !important; }
          .mobile-overlay { display: none !important; }
          .main-desktop { margin-left: 0 !important; padding-top: 96px !important; }
        }
        @media (max-width: 1023px) {
          .desktop-navbar { display: none !important; }
          .mobile-header { display: flex !important; }
          .main-desktop { padding-top: 24px !important; margin-left: 0 !important; }
        }
        @keyframes fadeInDown {
          from { opacity: 0; transform: translateY(-8px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes slideInLeft {
          from { transform: translateX(-100%); }
          to { transform: translateX(0); }
        }
      `}</style>

      {/* ═══════════════════════════════════════
          HEADER MÓVIL — VERSIÓN MOBILE/TABLET (<1024px)
          ═══════════════════════════════════════ */}
      <div
        className="mobile-header"
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          height: 64,
          background: colors.bgLight,
          borderBottom: `1px solid ${colors.border}`,
          boxShadow: '0 2px 10px rgba(0,0,0,0.06)',
          zIndex: 1000,
          display: 'none',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0 20px',
        }}
      >
        <button
          onClick={() => setMobileOpen(true)}
          style={{
            background: 'none',
            border: 'none',
            fontSize: 24,
            cursor: 'pointer',
            color: colors.textDark,
            padding: 4,
            borderRadius: 8,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          ☰
        </button>

        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div
            style={{
              width: 36,
              height: 36,
              borderRadius: 10,
              background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: 18,
            }}
          >
            🍽️
          </div>
          <span style={{ fontSize: 17, fontWeight: 800, color: colors.textDark }}>
            Restaurant <span style={{ color: colors.primary }}>AR</span>
          </span>
        </div>

        <div style={{ width: 36 }} /> {/* Spacer para centrar */}
      </div>

      {/* Overlay oscuro móvil */}
      {mobileOpen && (
        <div
          className="mobile-overlay"
          onClick={() => setMobileOpen(false)}
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.5)',
            backdropFilter: 'blur(4px)',
            zIndex: 1001,
            animation: 'fadeIn 0.2s ease',
          }}
        />
      )}

      {/* ═══════════════════════════════════════
          SIDEBAR MÓVIL — DRAWER DESLIZABLE
          ═══════════════════════════════════════ */}
      <aside
        className="mobile-sidebar"
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: 280,
          height: '100vh',
          background: colors.bgLight,
          zIndex: 1002,
          transform: mobileOpen ? 'translateX(0)' : 'translateX(-100%)',
          transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
          display: 'none',
          flexDirection: 'column',
          boxShadow: mobileOpen ? '10px 0 40px rgba(0,0,0,0.15)' : 'none',
        }}
      >
        {/* Header del drawer */}
        <div
          style={{
            padding: '24px 20px',
            borderBottom: `1px solid ${colors.border}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: 12,
                background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: 20,
                boxShadow: `0 4px 12px ${colors.primary}40`,
              }}
            >
              🍽️
            </div>
            <span style={{ fontSize: 18, fontWeight: 800, color: colors.textDark }}>
              Restaurant <span style={{ color: colors.primary }}>AR</span>
            </span>
          </div>
          <button
            onClick={() => setMobileOpen(false)}
            style={{
              background: 'none',
              border: 'none',
              fontSize: 22,
              cursor: 'pointer',
              color: colors.textSecondary,
              padding: 4,
            }}
          >
            ✕
          </button>
        </div>

        {/* Info de usuario en sidebar */}
        <div
          style={{
            padding: '20px',
            borderBottom: `1px solid ${colors.border}`,
            display: 'flex',
            alignItems: 'center',
            gap: 12,
          }}
        >
          <div
            style={{
              width: 44,
              height: 44,
              borderRadius: '50%',
              background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 700,
              color: '#fff',
              fontSize: 16,
              flexShrink: 0,
            }}
          >
            {user?.name?.charAt(0)?.toUpperCase()}
          </div>
          <div style={{ overflow: 'hidden' }}>
            <p
              style={{
                margin: 0,
                color: colors.textDark,
                fontSize: 14,
                fontWeight: 700,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}
            >
              {user?.name}
            </p>
            <p style={{ margin: 0, color: colors.textSecondary, fontSize: 12, marginTop: 2 }}>
              {user?.role?.name}
            </p>
          </div>
        </div>

        {/* Navegación */}
        <nav style={{ flex: 1, padding: '16px 12px', overflowY: 'auto' }}>
          <p
            style={{
              fontSize: 11,
              fontWeight: 700,
              color: colors.textSecondary,
              textTransform: 'uppercase',
              letterSpacing: '0.8px',
              padding: '0 12px',
              marginBottom: 8,
            }}
          >
            Menú Principal
          </p>
          {menuItems.map((item) => {
            const active = isActive(item.path);
            return (
              <button
                key={item.path}
                onClick={() => navigate(item.path)}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '12px 14px',
                  borderRadius: 12,
                  border: 'none',
                  background: active ? `${colors.primary}12` : 'transparent',
                  color: active ? colors.primary : colors.textSecondary,
                  fontSize: 14,
                  fontWeight: active ? 600 : 500,
                  cursor: 'pointer',
                  transition: 'all 0.2s',
                  marginBottom: 4,
                  textAlign: 'left',
                  position: 'relative',
                }}
              >
                <span
                  style={{
                    fontSize: 20,
                    filter: active ? 'none' : 'grayscale(30%)',
                    transition: 'filter 0.2s',
                  }}
                >
                  {item.icon}
                </span>
                {item.label}
                {active && (
                  <span
                    style={{
                      position: 'absolute',
                      left: 0,
                      top: '50%',
                      transform: 'translateY(-50%)',
                      width: 4,
                      height: 24,
                      borderRadius: '0 4px 4px 0',
                      background: colors.primary,
                    }}
                  />
                )}
              </button>
            );
          })}
        </nav>

        {/* Cerrar sesión */}
        <div style={{ padding: '16px 12px', borderTop: `1px solid ${colors.border}` }}>
          <button
            onClick={logout}
            style={{
              width: '100%',
              display: 'flex',
              alignItems: 'center',
              gap: 12,
              padding: '12px 14px',
              borderRadius: 12,
              border: 'none',
              background: `${colors.error}08`,
              color: colors.error,
              fontSize: 14,
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s',
              textAlign: 'left',
            }}
            onMouseEnter={(e) => (e.currentTarget.style.background = `${colors.error}15`)}
            onMouseLeave={(e) => (e.currentTarget.style.background = `${colors.error}08`)}
          >
            <span style={{ fontSize: 18 }}>🚪</span>
            Cerrar Sesión
          </button>
        </div>
      </aside>

      {/* ═══════════════════════════════════════
          CONTENIDO PRINCIPAL
          ═══════════════════════════════════════ */}
      <main
        className="main-desktop"
        style={{
          flex: 1,
          padding: '24px 32px',
          minHeight: '100vh',
          maxWidth: 1440,
          margin: '0 auto',
          width: '100%',
          boxSizing: 'border-box',
        }}
      >
        {children}
      </main>
    </div>
  );
};

export default DashboardLayout;
